27: __global__ void convert_vertical_slash_indexes_kernel(
28:     const int* seqlens,           // [BATCH, ]
29:     const int* vertical_indexes,  // [BATCH, N_HEADS, NNZ_V]
30:     const int* slash_indexes,     // [BATCH, N_HEADS, NNZ_S]
31:     int* block_count,             // [BATCH, N_HEADS, cdiv(N_CTX, BLOCK_SIZE_M)]
32:     int* block_offset,            // [BATCH, N_HEADS, cdiv(N_CTX, BLOCK_SIZE_M), NNZ_S]
33:     int* column_count,            // [BATCH, N_HEADS, cdiv(N_CTX, BLOCK_SIZE_M)]
34:     int* column_index,            // [BATCH, N_HEADS, cdiv(N_CTX, BLOCK_SIZE_M), NNZ_V]
35:     int N_HEADS,
36:     int N_ROWS,
37:     int BLOCK_SIZE_M,
38:     int BLOCK_SIZE_N,
39:     int NNZ_V,
40:     int NNZ_S
41: ) {
42:     const int batch_idx = blockIdx.y;
43:     const int head_idx = blockIdx.x;
44:     const int group_idx = blockIdx.z;
45: 
46:     int seqlen = seqlens[batch_idx];
47:     int block_idx_m = group_idx * blockDim.x + threadIdx.x;
48:     int start_m = block_idx_m * BLOCK_SIZE_M;
49:     if (start_m >= seqlen) {
50:         return;
51:     }
52:     int end_m = start_m + BLOCK_SIZE_M;
53:     vertical_indexes += (batch_idx * N_HEADS + head_idx) * NNZ_V;
54:     slash_indexes += (batch_idx * N_HEADS + head_idx) * NNZ_S;
55:     int row_offset = (batch_idx * N_HEADS + head_idx) * N_ROWS + block_idx_m;
56:     block_count += row_offset;
57:     block_offset += row_offset * NNZ_S;
58:     column_count += row_offset;
59:     column_index += row_offset * NNZ_V;
60: 
61:     int tmp_col_cnt = 0, tmp_blk_cnt = 0;
62:     int s = 0, v = 0;
63:     int v_idx = vertical_indexes[v++];
64:     int s_idx = slash_indexes[s++];
65:     while (s_idx >= end_m) {
66:         s_idx = slash_indexes[s++];
67:     }
68:     s_idx = max(end_m - s_idx, BLOCK_SIZE_M);
69:     int range_start = s_idx - BLOCK_SIZE_M, range_end = s_idx;
70:     while (1) {
71:         if (v_idx < range_end) {
72:             if (v_idx < range_start) {
73:                 column_index[tmp_col_cnt++] = v_idx;
74:             }
75:             if (v < NNZ_V) {
76:                 v_idx = vertical_indexes[v++];
77:             } else {
78:                 v_idx = end_m + BLOCK_SIZE_M;
79:             }
80:         } else {
81:             if (s < NNZ_S) {
82:                 s_idx = max(end_m - slash_indexes[s++], BLOCK_SIZE_M);
83:             } else {
84:                 save_blocks(block_offset, range_start, range_end, BLOCK_SIZE_N, tmp_blk_cnt);
85:                 break;
86:             }
87:             if (s_idx > range_end + BLOCK_SIZE_M) {
88:                 save_blocks(block_offset, range_start, range_end, BLOCK_SIZE_N, tmp_blk_cnt);
89:                 range_start = s_idx - BLOCK_SIZE_M;
90:                 range_end = s_idx;
91:             } else if (s_idx > range_end) {
92:                 range_end += BLOCK_SIZE_M;
93:             }
94:         }
95:     }
96: 
97:     block_count[0] = tmp_blk_cnt;
98:     column_count[0] = tmp_col_cnt;
99: }
