101: void convert_vertical_slash_indexes_64x64(
102:     const int* seqlens,           // [BATCH, ]
103:     const int* vertical_indexes,  // [BATCH, N_HEADS, NNZ_V]
104:     const int* slash_indexes,     // [BATCH, N_HEADS, NNZ_S]
105:     int* block_count,             // [BATCH, N_HEADS, cdiv(N_CTX, BLOCK_SIZE_M)]
106:     int* block_offset,            // [BATCH, N_HEADS, cdiv(N_CTX, BLOCK_SIZE_M), NNZ_S]
107:     int* column_count,            // [BATCH, N_HEADS, cdiv(N_CTX, BLOCK_SIZE_M)]
108:     int* column_index,            // [BATCH, N_HEADS, cdiv(N_CTX, BLOCK_SIZE_M), NNZ_V]
109:     int BATCH_SIZE,
110:     int N_HEADS,
111:     int N_ROWS,
112:     int NNZ_V,
113:     int NNZ_S
114: ) {
115:     const int BLOCK_SIZE_M = 64;
116:     const int BLOCK_SIZE_N = 64;
117:     const int N_THREADS = 64;
118:     const dim3 dimBlock(N_THREADS);
119:     const dim3 dimGrid(N_HEADS, BATCH_SIZE, (N_ROWS + N_THREADS - 1) / N_THREADS);
120:     convert_vertical_slash_indexes_kernel<<<dimGrid, dimBlock>>>(
121:         seqlens, vertical_indexes, slash_indexes,
122:         block_count, block_offset, column_count, column_index,
123:         N_HEADS, N_ROWS, BLOCK_SIZE_M, BLOCK_SIZE_N, NNZ_V, NNZ_S
124:     );
125: }
