127: std::vector<at::Tensor> convert_vertical_slash_indexes(
128:     torch::Tensor seqlens,           // [BATCH, ]
129:     torch::Tensor vertical_indexes,  // [BATCH, N_HEADS, NNZ_V]
130:     torch::Tensor slash_indexes,     // [BATCH, N_HEADS, NNZ_S]
131:     int context_size,
132:     int block_size_M,
133:     int block_size_N
134: ) {
135:     assert(block_size_M == 64);
136:     assert(block_size_N == 64);
137: 
138:     cudaSetDevice(seqlens.get_device());
139: 
140:     int batch_size = slash_indexes.size(0);
141:     int num_heads = slash_indexes.size(1);
142:     int nnz_slash = slash_indexes.size(2);
143:     int nnz_vertical = vertical_indexes.size(2);
144:     int num_rows = (context_size + block_size_M - 1) / block_size_M;
145: 
146:     torch::Tensor block_count = torch::zeros({batch_size, num_heads, num_rows}, seqlens.options());
147:     torch::Tensor block_offset = torch::zeros({batch_size, num_heads, num_rows, nnz_slash}, seqlens.options());
148:     torch::Tensor column_count = torch::zeros({batch_size, num_heads, num_rows}, seqlens.options());
149:     torch::Tensor column_index = torch::zeros({batch_size, num_heads, num_rows, nnz_vertical}, seqlens.options());
150: 
151:     convert_vertical_slash_indexes_64x64(
152:         seqlens.data_ptr<int>(),
153:         vertical_indexes.data_ptr<int>(),
154:         slash_indexes.data_ptr<int>(),
155:         block_count.data_ptr<int>(),
156:         block_offset.data_ptr<int>(),
157:         column_count.data_ptr<int>(),
158:         column_index.data_ptr<int>(),
159:         batch_size,
160:         num_heads,
161:         num_rows,
162:         nnz_vertical,
163:         nnz_slash
164:     );
165: 
166:     return { block_count, block_offset, column_count, column_index };
167: }
